import{_ as l,a0 as d,w as s,s as p,I as i,x as t,a1 as n,A as o,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"將 Fedora Linux 系統添加到企業域中 | LCTT x X-CMD","titleTemplate":false,"description":"將 Fedora Linux 系統添加到企業域中 | LCTT (202105) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"將 Fedora Linux 系統添加到企業域中 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"將 Fedora Linux 系統添加到企業域中 | LCTT (202105) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202105/20210521 Joining Fedora Linux to an enterprise domain","title":"將 Fedora Linux 系統添加到企業域中","tag":"202105","desc":""},"relativePath":"202105/20210521 Joining Fedora Linux to an enterprise domain.md","filePath":"[post].md"}'),m={name:"202105/20210521 Joining Fedora Linux to an enterprise domain.md"};function u(f,e,g,x,L,b){const r=d("Link");return s(),p("div",null,[e[27]||(e[27]=i("h1",{id:"將-fedora-linux-系統添加到企業域中",tabindex:"-1"},[t("將 Fedora Linux 系統添加到企業域中 "),i("a",{class:"header-anchor",href:"#將-fedora-linux-系統添加到企業域中","aria-label":"Permalink to “將 Fedora Linux 系統添加到企業域中”"},"​")],-1)),e[28]||(e[28]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/202105/26/120149o01pzllgw119w66l.jpg",alt:""})],-1)),e[29]||(e[29]=i("p",null,"在企業互聯網場景中，一般情況下最廣泛使用的基於 Linux 的操作系統是 Red Hat Enterprise Linux（RHEL），它主要用於服務器，但也可以用作工作站。Fedora linux 其實也是工作站系統的一個很好的選擇，它提供了許多在企業環境中工作的特性，使管理成為一項簡單的任務。",-1)),i("p",null,[e[3]||(e[3]=t("當你的工作網絡中有許多機器時，你需要一種以集中方式管理用户和機器的方法。",-1)),n(r,{href:"https://www.freeipa.org/page/Main_Page"},{default:o(()=>[...e[0]||(e[0]=[t("FreeIPA",-1)])]),_:1}),e[4]||(e[4]=t(" 和 ",-1)),i("ruby",null,[n(r,{href:"https://en.wikipedia.org/wiki/Active_Directory"},{default:o(()=>[...e[1]||(e[1]=[t("活動目錄",-1)])]),_:1}),e[2]||(e[2]=i("rt",null,"Active Directory",-1))]),e[5]||(e[5]=t(" 就是用於這個任務的技術。它們允許系統管理員使用網絡中所有實體的目錄來管理大量的機器。",-1))]),e[30]||(e[30]=a('<h3 id="fedora-中的活動目錄" tabindex="-1">Fedora 中的活動目錄 <a class="header-anchor" href="#fedora-中的活動目錄" aria-label="Permalink to “Fedora 中的活動目錄”">​</a></h3><p>活動目錄在公司環境中非常常見。Fedora 和 RHEL 通過使用 SSSD （<ruby> 系統安全服務守護進程 <rt>System Security Services Daemon</rt></ruby>）與 FreeIPA 或活動目錄等服務很好地集成。SSSD 是一種訪問遠程目錄和身份驗證機制的系統服務。使用此軟件的計算機能夠使用遠程憑據進行身份驗證，並訪問該目錄網絡中可用的其他服務。</p><p>要加入域網絡，你需要域管理員的權限才能添加計算機。可以通過在域憑據上設置特殊權限或代表你對該計算機進行預配置。Fedora Linux 有一個在安裝時配置機器的選項，叫做<ruby>企業登錄<rt>Enterprise Login</rt></ruby>。如果你的計算機網絡自動配置為企業域網絡，那麼你可以直接使用域憑據登錄。</p><p><img src="https://lh5.googleusercontent.com/aIRYn2TDgaaUrErzBV_KPVgpm94OrVgySlwqlI3VsotslWKN5UnLQ0VYjESSFB12aZWf_UnbmOOwa_rcxvRoI-MB6gFaw8p-RgBP9Lswnb2YV3iIlQ8YeXgpwJC_-B5tPrFTfUe_" alt=""></p><p>如果你的配置不是自動的，或者你已經安裝了 Fedora Linux，你可以通過以下幾個配置步驟加入一個活動目錄域：</p><ol><li>設置此計算機的 DNS。要連接到目錄服務，首先需要能夠解析目錄域名。如果你的網絡使用 DHCP 設置正確的 DNS，則可以跳過此步驟。</li><li>更改你的計算機名稱，以反映它將是新域的一部分。編輯文件 <code>/etc/hostname</code>，並將機器名更改為 <code>machinename.my_domain</code>。</li><li>通過執行以下命令加入域：<code>sudo realm join my_domain -v</code>（ 用域名稱替換 <code>my_domain</code>）。</li></ol><p>運行此命令後，系統將請求允許加入該域中新計算機的用户的憑據。如果進程中沒有錯誤，則機器將成為域的一部分。</p><p><img src="https://lh6.googleusercontent.com/DVvr7cHuZxvgqhAHk9v7jAYSER7VSP1G7CJ1xHx1kT5ZS-v1yt3rKMmwk9JhsLnYGfwAjOPPpSC2BGTpZtAdKrnx7XLUWgOZBhFFwB6SL7vR_q_2N1c_OGYp7YmNLRk7oRW8IEVB" alt=""></p><p>現在，此計算機已成為你的域的一部分，你可以：</p><ul><li>使用域用户名登錄到計算機</li><li>獲取 kerberos 票據以訪問域網絡中的不同服務</li><li>訪問其他服務，具體取決於域的配置方式</li></ul><h3 id="使用-fleet-commander-管理-fedora-linux" tabindex="-1">使用 Fleet Commander 管理 Fedora Linux <a class="header-anchor" href="#使用-fleet-commander-管理-fedora-linux" aria-label="Permalink to “使用 Fleet Commander 管理 Fedora Linux”">​</a></h3><p>現在這台計算機已經是你的域的一部分了，你可以使用活動目錄的域管理員工具來管理它。由於你的計算機沒有運行 Windows，因此你只能進行身份驗證以及訪問網絡和目錄服務。無法在此計算機上設置與桌面相關的配置。</p>',12)),i("p",null,[e[7]||(e[7]=t("幸運的是，Fedora 有個工具叫 ",-1)),n(r,{href:"https://fleet-commander.org/"},{default:o(()=>[...e[6]||(e[6]=[t("Fleet Commander",-1)])]),_:1}),e[8]||(e[8]=t("。",-1))]),e[31]||(e[31]=a('<h4 id="創建配置" tabindex="-1">創建配置 <a class="header-anchor" href="#創建配置" aria-label="Permalink to “創建配置”">​</a></h4><p>Fleet Commander 是一個管理工具，允許你為網絡中的所有 Fedora Linux 機器設置桌面配置文件。</p><p>這意味着，你可以簡單地為 GNOME 桌面、Firefox、Chrome、LibreOffice 和其他支持的軟件設置任何配置，然後在登錄到選定的用户/組/計算機時以細粒度的方式應用該配置。</p><p><img src="https://lh6.googleusercontent.com/ATeNp5niX37MW7ARiMVSkqe9Vr5Fv4IN6eUW5xf1UPO0AMO1DxXLypw0CbqTNOfzLJYDM18ggc7Mrh3LZK8Foh80K1WjSW9LHQD081BbJg0owQJj_ZQdICLr0tGILmBRco-xbq92" alt=""></p><p>要使用這個工具首先安裝 <code>fleet-commander-admin</code> 軟件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install fleet-commander-admin</span></span></code></pre></div>',6)),i("p",null,[e[10]||(e[10]=t("然後，用瀏覽器訪問 ",-1)),n(r,{href:"http://localhost:9090/"},{default:o(()=>[...e[9]||(e[9]=[t("http://localhost:9090",-1)])]),_:1}),e[11]||(e[11]=t(" 來登錄。在左邊的菜單中，點擊 “Fleet Commander”。",-1))]),e[32]||(e[32]=a('<p>Fleet Commander 有一個工具，可以使用“實時會話”機制直觀地設置配置概要文件。它運行一個虛擬機，作為基本機器的模板。你需要手動進行所需的配置更改。然後檢查所有配置更改，選擇要添加到配置文件中的更改，然後部署它。</p><h4 id="管理客户端" tabindex="-1">管理客户端 <a class="header-anchor" href="#管理客户端" aria-label="Permalink to “管理客户端”">​</a></h4><p>在每個 Fedora Linux 或 RHEL 機器中，你都需要安裝 Fleet Commander 客户端服務。此服務在用户登錄時激活。它在域中搜索應用於當前用户/計算機的配置文件，並應用這個配置。</p><p>安裝 <code>fleet-commander-client</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install fleet-commander-client</span></span></code></pre></div><p>軟件將自動檢測機器是否是域的一部分。當用户登錄時，它將使用應用於該用户的配置文件來設置會話。</p><hr>',7)),i("p",null,[e[13]||(e[13]=t("via: ",-1)),n(r,{href:"https://fedoramagazine.org/join-fedora-linux-enterprise-domain/"},{default:o(()=>[...e[12]||(e[12]=[t("https://fedoramagazine.org/join-fedora-linux-enterprise-domain/",-1)])]),_:1})]),i("p",null,[e[18]||(e[18]=t("作者：",-1)),n(r,{href:"https://fedoramagazine.org/author/ogutierrez/"},{default:o(()=>[...e[14]||(e[14]=[t("ogutierrez",-1)])]),_:1}),e[19]||(e[19]=t(" 選題：",-1)),n(r,{href:"https://github.com/lujun9972"},{default:o(()=>[...e[15]||(e[15]=[t("lujun9972",-1)])]),_:1}),e[20]||(e[20]=t(" 譯者：",-1)),n(r,{href:"https://github.com/Chao-zhi"},{default:o(()=>[...e[16]||(e[16]=[t("Chao-zhi",-1)])]),_:1}),e[21]||(e[21]=t(" 校對：",-1)),n(r,{href:"https://github.com/wxy"},{default:o(()=>[...e[17]||(e[17]=[t("wxy",-1)])]),_:1})]),i("p",null,[e[24]||(e[24]=t("本文由 ",-1)),n(r,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[22]||(e[22]=[t("LCTT",-1)])]),_:1}),e[25]||(e[25]=t(" 原創編譯，",-1)),n(r,{href:"https://linux.cn/"},{default:o(()=>[...e[23]||(e[23]=[t("Linux中國",-1)])]),_:1}),e[26]||(e[26]=t(" 榮譽推出",-1))])])}const F=l(m,[["render",u]]);export{C as __pageData,F as default};
